arguments.command:
python3 -c "
import json
with open('/app/trial/agent/trajectory.json') as f:
    data = json.load(f)
steps = data['steps']
for i, s in enumerate(steps):
    tc = s.get('tool_calls')
    if tc:
        for t in tc:
            name = t.get('name') or t.get('tool_name')
            args = t.get('arguments') or t.get('input') or {}
            print(i, name, str(args)[:200])
"

raw_arguments.command:
python3 -c "
import json
with open('/app/trial/agent/trajectory.json') as f:
    data = json.load(f)
steps = data['steps']
for i, s in enumerate(steps):
    tc = s.get('tool_calls')
    if tc:
        for t in tc:
            name = t.get('name') or t.get('tool_name')
            args = t.get('arguments') or t.get('input') or {}
            print(i, name, str(args)[:200])
"

